private void checkFields(final Class<?> type) {
    if (type == null) return;

    // Reject abstract classes.
    if (Modifier.isAbstract(type.getModifiers())) {
        problems.add(new ValidityProblem("Delegate class is abstract"));
        return;
    }

    final List<Field> fields = ClassUtils.getAnnotatedFields(type, Parameter.class);

    for (final Field f : fields) {
        f.setAccessible(true); // expose private fields

        final Parameter param = f.getAnnotation(Parameter.class);
        final String name = f.getName();

        // Check for final modifier
        if (Modifier.isFinal(f.getModifiers()) && param.visibility() != ItemVisibility.MESSAGE) {
            problems.add(new ValidityProblem("Invalid final parameter: " + f));
            continue;
        }

        // Check for duplicate parameter names
        if (inputMap.containsKey(name) || outputMap.containsKey(name)) {
            problems.add(new ValidityProblem("Invalid duplicate parameter: " + f));
            continue;
        }

        // Check for immutable BOTH parameters
        if (param.type() == ItemIO.BOTH && isImmutable(f.getType())) {
            problems.add(new ValidityProblem("Immutable BOTH parameter: " + f));
            continue;
        }

        final boolean isPreset = presets.containsKey(name);

        // Add item to the relevant list (inputs or outputs)
        final CommandModuleItem<Object> item = new CommandModuleItem<>(this, f);
        if (item.isInput()) {
            inputMap.put(name, item);
            if (!isPreset) inputList.add(item);
        }
        if (item.isOutput()) {
            outputMap.put(name, item);
            if (!isPreset) outputList.add(item);
        }
    }
}

